#include <iostream>
using namespace std;

int main() {
    long long a, b;
    cin >> a >> b;

    if (a == b) {
        cout << "infinity\n";
        return 0;
    }

    if (a < b) {
        cout << 0 << '\n';
        return 0;
    }

    long long difference = a - b;
    long long count = 0;

    for (long long i = 1; i <= difference / i; ++i) {
        if (difference % i == 0) {
            long long other = difference / i;

            if (i > b)
                ++count;
            if (other != i && other > b)
                ++count;
        }
    }

    cout << count << '\n';
    return 0;
}

